  const ram = sanitizeRam(ns.args[0], 2 ** 12);
  const skipPrompt = ns.args[1] === true || String(ns.args[1] || "").toLowerCase() === "true";

  const servers = ns.getPurchasedServers().filter(s => s.startsWith("MeinServer_"));
