export async function main(ns) {
  const file = ns.args[0] || DEFAULT_FILE;
  const sampleMs = Number(ns.args[1] || DEFAULT_SAMPLE_MS);
  const maxSamples = Number(ns.args[2] || DEFAULT_MAX_SAMPLES);

  ns.disableLog("sleep");
  ns.disableLog("write");
