    let body = "";
    res.setHeader("Content-Type", "application/json");

    req.on("data", (chunk) => {
      body += chunk.toString(); // convert Buffer to string
    });

    req.on("end", async () => {
      const providedToken = req.headers?.authorization?.replace("Bearer ", "") ?? "";
