${files.map((f, i) => `AllPages["${f}"] = file${i};`).join("\n")}
`;

fs.writeFile(docRoot + "/../pages.ts", autogenfile, (err) => {
  if (err) {
    console.error(err);
  }
  // file written successfully
});
