  "data structures": 40,
  networks: 80,
  algorithms: 320,
  management: 160,
  leadership: 320,
};

const UNIVERSITY_COURSE_TYPES = {
  "study computer science": "Computer Science",
  "computer science": "Computer Science",
  "data structures": "Data Structures",
  networks: "Networks",
  algorithms: "Algorithms",
  management: "Management",
